class Solution {
public:
    vector<int> replaceWithRank(vector<int>& arr) {
        int n = arr.size();

        priority_queue<pair<int, int>, vector<pair<int,int>>, greater<pair<int, int>>> pq;     // Min Heap

        for(int i=0;i<n;i++){
            pq.push({arr[i], i});
        }

        vector<int> ans(n, 0);
        int prev = INT_MIN;
        int rank = 0;
        while(!pq.empty()){
            int topElement = pq.top().first;
            int index = pq.top().second;

            pq.pop();

            if(topElement != prev) rank++;
            ans[index] = rank;

            prev = topElement;
        }

        return ans;

    }
};
